// Collects the output of the earlier nodes and builds one report.
const settings = $('Set report settings').first().json;
const lookbackDays = Number(settings.lookbackDays) || 7;
const since = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);
const baseUrl = String(settings.instanceUrl || '').replace(/\/+$/, '');

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const parse = (v) => v.split('.').map(Number);
const cmp = (a, b) => {
  const x = parse(a), y = parse(b);
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
};

// 1. Running version: metrics first, security audit text second
let current = null;
let versionSource = 'not available';
const metrics = String($('Read version from metrics').first().json.data || '');
const metricsMatch = metrics.match(/version_info\{[^}]*version="v?(\d+\.\d+\.\d+)"/);
if (metricsMatch) {
  current = metricsMatch[1];
  versionSource = 'Prometheus metrics';
}

const auditText = JSON.stringify($('Run security audit').all().map((i) => i.json));
const auditMatch = auditText.match(/Currently at version (\d+\.\d+\.\d+), missing (\d+) update/);
if (!current && auditMatch) {
  current = auditMatch[1];
  versionSource = 'security audit';
}
const auditSaysSecurityUpdates = auditText.includes('Newer versions contain security updates');

// Section titles from the audit report, e.g. "Outdated instance", "Unprotected webhooks in instance"
const auditFindings = [];
for (const item of $('Run security audit').all()) {
  for (const report of Object.values(item.json || {})) {
    if (report && Array.isArray(report.sections)) {
      // "Security settings" is informational and appears on every instance; it is not a risk
      for (const s of report.sections) if (s.title !== 'Security settings') auditFindings.push(s.title);
    }
  }
}

// 2. Stable releases from GitHub
const releases = $('Get n8n releases from GitHub').all()
  .map((i) => i.json)
  .filter((r) => r && !r.draft && !r.prerelease && /^n8n@\d+\.\d+\.\d+$/.test(r.tag_name || ''))
  .map((r) => ({ version: r.tag_name.slice(4), url: r.html_url, published: (r.published_at || '').slice(0, 10) }))
  .sort((a, b) => cmp(b.version, a.version));
const latest = releases[0] || null;

let status = 'unknown';
let newerCount = 0;
let linePatches = [];
if (current && latest) {
  const [maj, min] = parse(current);
  newerCount = releases.filter((r) => cmp(r.version, current) > 0).length;
  linePatches = releases.filter((r) => {
    const [a, b] = parse(r.version);
    return a === maj && b === min && cmp(r.version, current) > 0;
  });
  status = cmp(current, latest.version) >= 0 ? 'up to date' : 'update available';
} else if (!current && !auditMatch && auditText.length > 2) {
  status = 'no missing updates reported by the audit';
}

// 3. Failed executions in the look-back window
const names = {};
for (const w of $('Get workflow names').all()) if (w.json && w.json.id) names[w.json.id] = w.json.name;

const failed = $('Get failed executions').all()
  .map((i) => i.json)
  .filter((e) => e && e.id && e.startedAt && new Date(e.startedAt) >= since);

const byWorkflow = {};
for (const e of failed) {
  const g = (byWorkflow[e.workflowId] ??= { workflowId: e.workflowId, name: names[e.workflowId] || `Workflow ${e.workflowId}`, count: 0, lastAt: '', lastId: '' });
  g.count++;
  if (!g.lastAt || e.startedAt > g.lastAt) { g.lastAt = e.startedAt; g.lastId = e.id; }
}
const groups = Object.values(byWorkflow).sort((a, b) => b.count - a.count);

// 4. Build the report
const headline = status === 'update available'
  ? `update available (${current} -> ${latest.version})`
  : status;
const subject = `n8n health: ${headline}; ${failed.length} failed execution${failed.length === 1 ? '' : 's'} in ${lookbackDays} days`;

const lines = [];
lines.push(`Running version: ${current || 'unknown'} (source: ${versionSource})`);
if (latest) lines.push(`Latest stable release: ${latest.version} (${latest.published})`);
if (newerCount) lines.push(`Newer stable releases: ${newerCount}`);
if (linePatches.length) lines.push(`Patches on your release line: ${linePatches.map((r) => r.version).join(', ')}`);
if (auditSaysSecurityUpdates) lines.push('The security audit says newer versions contain security updates.');
if (auditFindings.length) lines.push(`Audit findings: ${auditFindings.join('; ')}`);
lines.push(`Failed executions (last ${lookbackDays} days): ${failed.length}`);
for (const g of groups) lines.push(`- ${g.name}: ${g.count}`);
const summary = lines.join('\n');

const link = (g) => baseUrl ? `<a href="${esc(`${baseUrl}/workflow/${g.workflowId}/executions/${g.lastId}`)}">${esc(g.lastAt.slice(0, 16).replace('T', ' '))}</a>` : esc(g.lastAt.slice(0, 16).replace('T', ' '));
const rows = groups.map((g) => `<tr><td>${esc(g.name)}</td><td style="text-align:right">${g.count}</td><td>${link(g)}</td></tr>`).join('');

const html = `
<h2>n8n instance health report</h2>
<h3>Version</h3>
<p>Running: <b>${esc(current || 'unknown')}</b> (source: ${esc(versionSource)})<br>
Latest stable: ${latest ? `<a href="${esc(latest.url)}">${esc(latest.version)}</a> (${esc(latest.published)})` : 'could not read GitHub releases'}<br>
Status: <b>${esc(headline)}</b></p>
${linePatches.length ? `<p>Newer patches on your release line: ${linePatches.map((r) => `<a href="${esc(r.url)}">${esc(r.version)}</a>`).join(', ')}. These usually carry bug and security fixes and are the safest update to take first.</p>` : ''}
${auditSaysSecurityUpdates ? '<p style="color:#b42318"><b>The n8n security audit reports that newer versions contain security updates.</b></p>' : ''}
<h3>Security audit</h3>
<p>${auditFindings.length ? esc(auditFindings.join('; ')) : 'No risks reported.'}</p>
<h3>Failed executions, last ${lookbackDays} days: ${failed.length}</h3>
${groups.length ? `<table cellpadding="6" style="border-collapse:collapse" border="1"><tr><th>Workflow</th><th>Failures</th><th>Most recent</th></tr>${rows}</table>` : '<p>None.</p>'}
${failed.length >= 250 ? '<p>Only the 250 most recent failures were checked.</p>' : ''}
`;

return [{ json: { subject, summary, html, current, latest: latest ? latest.version : null, status, failedCount: failed.length } }];
